<script setup>
import {ref} from 'vue';
import {FolderPlus,Folder,Pencil,Trash2,X,Check} from 'lucide-vue-next';
const props=defineProps(['folders','api']);const emit=defineEmits(['close','changed']);
const name=ref(''),parent=ref(''),renaming=ref(''),newName=ref(''),error=ref(''),busy=ref(false);
async function act(method,body){busy.value=true;error.value='';try{const r=await props.api('/folders',{method,body:JSON.stringify(body)});emit('changed',{method,path:r.path,oldPath:body.path});if(parent.value===body.path)parent.value=r.path||'';name.value='';renaming.value='';}catch(e){error.value=e.message;}finally{busy.value=false;}}
</script>
<template><div class="modal-backdrop folder-modal" @click.self="emit('close')"><section class="folder-dialog"><div class="section-top"><div><div class="eyebrow">A PLACE FOR EVERY IDEA</div><h2>整理你的知识文件夹</h2></div><button class="icon-button" aria-label="关闭文件夹管理" @click="emit('close')"><X/></button></div><p>按学科、项目或兴趣建立层级，让每篇笔记都有自己的位置。</p><form class="folder-create" @submit.prevent="act('POST',{name,parent})"><label>放在<select v-model="parent"><option value="">根目录</option><option v-for="f in folders" :value="f.path">{{f.path}}</option></select></label><label>文件夹名称<input v-model="name" required maxlength="50" placeholder="例如：前端开发" pattern="[^/\\]+"/></label><button class="primary" :disabled="busy"><FolderPlus :size="16"/>新建</button></form><div v-if="error" class="error" role="alert">{{error}}</div><div class="folder-list"><div v-for="f in folders" class="folder-item" :style="{paddingLeft:12+f.path.split('/').length*12+'px'}"><Folder :size="17"/><template v-if="renaming!==f.path"><span>{{f.path.split('/').at(-1)}}</span><button class="icon-button" :aria-label="'重命名 '+f.path" @click="renaming=f.path;newName=f.path.split('/').at(-1)"><Pencil :size="14"/></button><button class="icon-button" :disabled="busy" :aria-label="'删除空文件夹 '+f.path" @click="act('DELETE',{path:f.path})"><Trash2 :size="14"/></button></template><form v-else class="rename-form" @submit.prevent="act('PUT',{path:f.path,name:newName})"><input v-model="newName" required maxlength="50" aria-label="新文件夹名称"/><button class="icon-button" :disabled="busy" aria-label="确认重命名"><Check :size="16"/></button><button type="button" class="icon-button" aria-label="取消重命名" @click="renaming=''"><X :size="16"/></button></form></div><div v-if="!folders.length" class="empty">新建第一个文件夹，开始整理知识。</div></div><p class="hint">重命名会同步更新子文件夹和笔记归属。只有空文件夹可以删除。</p></section></div></template>

